head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf91100";
scwin.crtvl_sf1 = undefined;
scwin.crtvl_sf2 = undefined;
scwin.crtvl_sf3 = undefined;
scwin.crtvl_sf4 = undefined;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — crtvlList, callList, putList, crtvl_sf1, crtvl_sf2, crtvl_sf3, crtvl_sf4

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf91100.onpageload' });
    }
};

