tion(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='01'); } }, { id: "if_coupnRtDecsnBasIntCd_2_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='02'); } }, { id: "if_coupnRtDecsnBasIntCd_3_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='03'); } }, { id: "if_coupnRtDecsnBasIntCd_4_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='04'); } }, { id: "if_coupnRtDecsnBasIntCd_5_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='05'); } }, { id: "if_coupnRtDecsnBasIntCd_6_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='06'); } }, { id: "if_coupnRtDecsnBasIntCd_7_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='07'); } }, { id: "if_coupnRtDecsnBasIntCd_8_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='08'); } }, { id: "if_coupnRtDecsnBasIntCd_9_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='10'); } }, { id: "if_coupnRtDecsnBasIntCd_10_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='12'); } }, { id: "if_coupnRtDecsnBasIntCd_11_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='20'); } }, { id: "if_coupnRtDecsnBasIntCd_12_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='21'); } }, { id: "if_coupnRtDecsnBasIntCd_13_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='31'); } }, { id: "if_coupnRtDecsnBasIntCd_14_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='32'); } }, { id: "if_coupnRtDecsnBasIntCd_15_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='33'); } }, { id: "if_coupnRtDecsnBasIntCd_16_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='34'); } }, { id: "if_coupnRtDecsnBasIntCd_17_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='35'); } }, { id: "if_coupnRtDecsnBasIntCd_18_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='36'); } }, { id: "if_coupnRtDecsnBasIntCd_19_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='37'); } }, { id: "if_coupnRtDecsnBasIntCd_20_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='38'); } }, { id: "if_coupnRtDecsnBasIntCd_21_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='39'); } }, { id: "if_coupnRtDecsnBasIntCd_22_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='40'); } }, { id: "if_coupnRtDecsnBasIntCd_23_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='41'); } }, { id: "if_coupnRtDecsnBasIntCd_24_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='42'); } }, { id: "if_coupnRtDecsnBasIntCd_25_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='43'); } }, { id: "if_coupnRtDecsnBasIntCd_26_txt", fn: function(){ return ((dma_map.get("coupnRtDecsnBasIntCd") ?? (() => { throw new Error("unresolved:" + "map.coupnRtDecsnBasIntCd"); })())==='90'); } }, { id: "c_when_483", fn: function(){ return (!(String(((dma_pageContext.get("callList") ?? "")) == null ? '' : ((dma_pageContext.get("callList") ?? ""))).length === 0)); } }, { id: "tr_485", fn: function(){ return (!(String(((dma_pageContext.get("callList") ?? "")) == null ? '' : ((dma_pageContext.get("callList") ?? ""))).length === 0)); } }, { id: "c_otherwise_489", fn: function(){ return (!((!(String(((dma_pageContext.get("callList") ?? "")) == null ? '' : ((dma_pageContext.get("callList") ?? ""))).length === 0)))); } }, { id: "c_when_510", fn: function(){ return (!(String(((dma_pageContext.get("putList") ?? "")) == null ? '' : ((dma_pageContext.get("putList") ?? ""))).length === 0)); } }, { id: "tr_512", fn: function(){ return (!(String(((dma_pageContext.get("putList") ?? "")) == null ? '' : ((dma_pageContext.get("putList") ?? ""))).length === 0)); } }, { id: "c_otherwise_516", fn: function(){ return (!((!(String(((dma_pageContext.get("putList") ?? "")) == null ? '' : ((dma_pageContext.get("putList") ?? ""))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_484", entity: "dlt_callList", countIds: [], cells: [{ childId: "__rc82", fn: function (v, i) { return String(v("callExerStrtDate")); } }, { childId: "__rc83", fn: function (v, i) { return String(v("callExerEndDate")); } }] },
        { genId: "c_foreach_511", entity: "dlt_putList", countIds: [], cells: [{ childId: "__rc86", fn: function (v, i) { return String(v("putExerStrtDate")); } }, { childId: "__rc87", fn: function (v, i) { return String(v("putExerEndDate")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_stdcdType", fn: function () { return String((dma_pageContext.get("stdcdType") ?? "")); } },
        { childId: "ipt_stdCd", fn: function () { return String((dma_pageContext.get("stdCd") ?? "")); } },
        { childId: "__rb4", fn: function () { return String(dma_map.get("bndClssNm")) + " (" + String(dma_map.get("bndClssCd")) + ")"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.setViewTable();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91100.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldinf91100: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_goModify_onclick
 * @description btn_goModify 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goModify_onclick = async function(e){
    try {
        await scwin.go_modify()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf91100.btn_goModify_onclick' }); }
};

/**
 * @method
 * @name btn_goDelete_onclick
 * @description btn_goDelete 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goDelete_onclick = function(e){
    try {
        scwin.go_delete()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91100.btn_goDelete_onclick' }); }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91100.btn_self_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_go_modify
 * @description go modify 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_go_modify = async function () {
    const sbmOptions = {
        id: "tx_go_modify",
        method: "post",
        action: "/stdcd/stdcdModify.do?method=stdcdModify",
        ref: "dma_goModifyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setViewTable
 * @description set View Table 처리
 * @returns {void}
 * @hidden N
 */
scwin.setViewTable = function () {
    if ('' + dma_map.get("nusual_bnd_tp_cd") + '' === "2") {
        $c.util.getComponent("txt_titleNusualBndTpCd").setStyle("display", "");
        $c.util.getComponent("id_nusual_bnd_tp_cd").setStyle("display", "");
    }
    const int_pay_methd_cd = '' + dma_map.get("int_pay_methd_cd") + '';
    if (int_pay_methd_cd === "22" || int_pay_methd_cd === "23") {
        $c.util.getComponent("txt_titleIntPayMethdCd").setStyle("display", "");
        $c.util.getComponent("id_int_pay_methd_cd").setStyle("display", "");
    }
    const imbdopt_corpbnd_cd = '' + dma_map.get("imbdopt_corpbnd_cd") + '';
    if (imbdopt_corpbnd_cd === "1") {
        $c.util.getComponent("txt_titleOption").setStyle("display", "");
        $c.util.getComponent("id_call_option").setStyle("display", "");
    }
    if (imbdopt_corpbnd_cd === "2") {
        $c.util.getComponent("txt_titleOption").setStyle("display", "");
        $c.util.getComponent("id_put_option").setStyle("display", "");
    }
    if (imbdopt_corpbnd_cd === "3") {
        $c.util.getComponent("txt_titleOption").setStyle("display", "");
        $c.util.getComponent("id_call_option").setStyle("display", "");
        $c.util.getComponent("id_put_option").setStyle("display", "");
    }
    const redmpt_methd_tp_cd = '' + dma_map.get("redmpt_methd_tp_cd") + '';
    if (redmpt_methd_tp_cd === "2") {
        $c.util.getComponent("txt_titleRedmptMethdTpCd").setStyle("display", "");
        if ('' + dma_map.get("split_redmpt_tp_cd") + '' === "1" || '' + dma_map.get("split_redmpt_tp_cd") + '' === "2") {
            $c.util.getComponent("id_redmpt_methd_tp_cd").setStyle("display", "");
        } else {
            if ('' + dma_map.get("split_redmpt_tp_cd") + '' === "3") {
                $c.util.getComponent("id_redmpt_methd_tp_cd_list").setStyle("display", "");
            }
        }
    }
    const asst_secutiz_tp_cd = '' + dma_map.get("asst_secutiz_tp_cd") + '';
    if (asst_secutiz_tp_cd !== "") {
        $c.util.getComponent("txt_titleAsstSecutizTpCd").setStyle("display", "");
        $c.util.getComponent("id_asst_secutiz_tp_cd").setStyle("display", "");
    }
};

