/**
 * @method
 * @name print
 * @description print 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.print = async function () {
    if (!await $c.win.confirm("채권 상세정보를 출력하시겠습니까?")) {
        return false;
    } else {
        const std_cd = $c.util.getComponent('dma_goModifyReq').get('stdCd');
        const rexName = "JLDINF91100";
        const dataType = "XML";
        const dataLocation = "/srch/srch.do?method=srchReport3&std_cd=" + std_cd;
        const dataXPath = "main/rpt1";
        const mktGubun = "1";
        fn_PrintPreView_DB(rexName, dataType, dataLocation, dataXPath);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_PrintPreView_DB — 외부 리포트 도구(rexpert)
    }
};
